import { $authHost } from "./index";

export const createOrder = async (order) => {
    const {data} = await $authHost.post('api/order', order)
    
    return data
}

export const getAllOrders = async () => {
    const {data} = await $authHost.get('api/order')
    return data
}

export const getOneOrder = async (id) => {
    const {data} = await $authHost.get('api/order', {params:{ id}})
    return data
}

export const getOneOrderInfo = async (id) => {
    const {data1, data2} = await $authHost.get('api/order/' + id)
    console.log(JSON({data1, data2}))
    return data1, data2
}

export const delOrder = async () => {
    const {data} = await $authHost.delete('api/order')
    return data
}
